// A TypeScript package (as workspace packages often are): types are stripped when bundling.
export enum Kind { Circle, Square = 10, Other }
export interface Shape { kind: Kind; size: number }
type Area = (s: Shape) => number;
export const area: Area = (s: Shape): number => s.kind === Kind.Circle ? Math.round(Math.PI * s.size ** 2) : s.size * s.size;
export class Box<T> {
  constructor(private readonly items: T[] = []) {}
  add(item: T): this { this.items.push(item); return this; }
  get size(): number { return this.items.length; }
}
